import fp from 'fastify-plugin';

/** Every response carries X-Request-Id (ids are generated by Fastify's genReqId, see app.ts). Set early so error replies have it too. */
export default fp(async (app) => {
  app.addHook('onRequest', async (req, reply) => {
    reply.header('X-Request-Id', req.id);
  });
}, { name: 'request-id' });
